import{_ as t,o as a,c as n,a5 as r}from"./chunks/framework.CXroN2RO.js";const o="/study/images/game/scenes-and-components.svg",p=JSON.parse('{"title":"シーン・オブジェクト・コンポーネントの基本","description":"","frontmatter":{"title":"シーン・オブジェクト・コンポーネントの基本","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"ゲーム内の物をシーンに配置し、位置や描画、当たり判定の部品を組み合わせる考え方を説明する。親子関係と、Unity・Unreal Engineの用語もつなげる。","aliases":["シーン","scene","ゲームオブジェクト","GameObject","コンポーネント","Component","Transform","親子関係","ヒエラルキー","Actor","ActorComponent","SceneComponent"],"verification":"Unity 6.0のシーン・GameObject・TransformとUnreal EngineのActor・Componentの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/scenes-and-components.md","filePath":"game/basics/scenes-and-components.md"}'),s={name:"game/basics/scenes-and-components.md"};function i(c,e,m,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="シーン・オブジェクト・コンポーネントの基本" tabindex="-1">シーン・オブジェクト・コンポーネントの基本 <a class="header-anchor" href="#シーン・オブジェクト・コンポーネントの基本" aria-label="Permalink to &quot;シーン・オブジェクト・コンポーネントの基本&quot;">​</a></h1><p>プレイヤー、地面、カメラ、照明などを配置し、それぞれの役割を組み合わせて遊べる場面を作ります。主にUnityを例に、オブジェクトを配置して機能を持たせる方法を扱います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/CreatingScenes.html" target="_blank" rel="noreferrer">Unityのシーン</a> · <a href="/study/game/basics/game-engine-basics.html">ゲームエンジンの基本</a></p><h2 id="シーンは、配置する内容をまとめる" tabindex="-1">シーンは、配置する内容をまとめる <a class="header-anchor" href="#シーンは、配置する内容をまとめる" aria-label="Permalink to &quot;シーンは、配置する内容をまとめる&quot;">​</a></h2><p><strong>シーン</strong>は、オブジェクトの配置や関連する設定をまとめる単位です。Unityでは、シーンをアセットとして保存し、読み込んでゲームを動かします。一つのシーンでゲーム全体を作ることも、複数のシーンを同時に読み込んで、背景とUIなどを分けて扱うこともできます。ステージとシーンの対応は、ゲームの構成によって決まります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/CreatingScenes.html" target="_blank" rel="noreferrer">Unityのシーンの役割</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/MultiSceneEditing.html" target="_blank" rel="noreferrer">複数シーンの読み込み</a></p><p><strong>オブジェクト</strong>という言葉は、ここではゲーム内の物や機能を表すまとまりとして使います。Unityの<strong>GameObject</strong>は、そのまとまりに名前を付け、<strong>コンポーネント</strong>という部品を付けて役割を持たせる仕組みです。例えば同じGameObjectに、位置、見た目、当たり判定、独自の操作処理を組み合わせます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/GameObjects.html" target="_blank" rel="noreferrer">UnityのGameObject</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/UsingComponents.html" target="_blank" rel="noreferrer">コンポーネントを使う</a></p><h2 id="コンポーネントが担当すること" tabindex="-1">コンポーネントが担当すること <a class="header-anchor" href="#コンポーネントが担当すること" aria-label="Permalink to &quot;コンポーネントが担当すること&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部品の例</th><th>担当すること</th></tr></thead><tbody><tr><td><strong>Transform</strong></td><td>位置、回転、大きさを表す。親子の配置関係も持つ。</td></tr><tr><td><strong>MeshFilter・MeshRenderer</strong></td><td>メッシュの参照を持ち、その形状とマテリアルを使って描画する。</td></tr><tr><td><strong>Collider</strong></td><td>当たり判定に使う形状を定める。</td></tr><tr><td><strong>Rigidbody</strong></td><td>質量などを持ち、物理シミュレーションでの移動を扱う。</td></tr><tr><td><strong>独自のスクリプト</strong></td><td>入力に応じた移動、HP、攻撃など、ゲーム固有の処理を持たせる。</td></tr></tbody></table><p>すべてのGameObjectが描画や物理の部品を持つ必要はありません。カメラだけを持つものや、他のオブジェクトをまとめるためのものも作れます。<strong>メッシュ</strong>は描画に使う形状、<strong>コライダー</strong>は当たり判定に使う形状です。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/UsingComponents.html" target="_blank" rel="noreferrer">Unityのコンポーネント</a> · <a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a> · <a href="/study/game/basics/collisions-and-physics.html">衝突と物理</a></p><figure class="study-figure"><img src="'+o+'" alt="シーン内にPlayerとGroundがあり、CameraはPlayerの子に配置されている。選択したPlayerにはTransform、描画、当たり判定、操作処理のコンポーネントが付く。親子の配置と、オブジェクトが持つ部品は別の関係として表す。" width="760" height="470" loading="lazy"><figcaption>左は配置の親子関係、右は一つのGameObjectが持つ部品の例です。<a href="/study/images/game/scenes-and-components.svg" target="_blank" rel="noopener noreferrer">シーンと部品の図を拡大</a></figcaption></figure><h2 id="親子関係で位置をまとめる" tabindex="-1">親子関係で位置をまとめる <a class="header-anchor" href="#親子関係で位置をまとめる" aria-label="Permalink to &quot;親子関係で位置をまとめる&quot;">​</a></h2><p>UnityのGameObjectはTransformによる<strong>親子関係</strong>を作れます。例えばPlayerを親、Cameraを子にすると、子のローカルな位置は親を基準に表せます。親の位置や回転が変わると、その変換を受けた場所に子も配置されます。この配置の階層を<strong>ヒエラルキー</strong>と呼びます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Transform.html" target="_blank" rel="noreferrer">UnityのTransformと親子関係</a></p><p>例えば回転や拡縮をしていない親がワールド位置<code>(10, 0, 0)</code>、子のローカル位置が<code>(0, 2, 0)</code>なら、子のワールド位置は<code>(10, 2, 0)</code>になります。親を右へ動かすと、子のローカル位置を変えずに一緒に動かせます。回転や拡縮も含む一般的な配置は、変換を組み合わせて求めます。<a href="/study/graphics/basics/transforms-and-cameras.html">座標とカメラの基本</a></p><h2 id="unreal-engineの名前を読む" tabindex="-1">Unreal Engineの名前を読む <a class="header-anchor" href="#unreal-engineの名前を読む" aria-label="Permalink to &quot;Unreal Engineの名前を読む&quot;">​</a></h2><p>Unreal Engineでは、レベルに配置するまとまりを<strong>Actor</strong>と呼びます。Actorに<strong>ActorComponent</strong>を付け、機能を組み合わせられます。位置や回転を持つ部品は<strong>SceneComponent</strong>で、Actorの位置はルートのSceneComponentを基準に扱います。ActorComponent全般が位置を持つわけではないため、部品の種類まで見ます。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/actors-in-unreal-engine" target="_blank" rel="noreferrer">Unreal EngineのActor</a> · <a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/components-in-unreal-engine" target="_blank" rel="noreferrer">Componentの種類</a></p><p>UnityのGameObjectとUnreal EngineのActorは、どちらも配置するまとまりを理解する入口になりますが、所有や寿命、実行の仕組みはそれぞれのエンジンで確認します。<a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponentの詳解</a></p><h2 id="配置データと、実行中に変わる状態" tabindex="-1">配置データと、実行中に変わる状態 <a class="header-anchor" href="#配置データと、実行中に変わる状態" aria-label="Permalink to &quot;配置データと、実行中に変わる状態&quot;">​</a></h2><p>同じ設定から敵や弾を作りたい場合は、<a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブとオブジェクトの寿命</a>へ進めます。</p><p>シーンに保存した配置から実行を始めると、移動したり、敵を生成したり、HPを減らしたりして状態が変わります。次回のプレイでも残したい情報は、ゲームが選んでセーブします。エディターで保存するシーンの配置と、プレイヤーの進行を保存する仕組みを、それぞれ用意します。<a href="/study/game/shooter-design.html">ゲームの小さな設計例</a> · <a href="/study/os/files-and-paths.html">ファイルとパス</a></p><p>部品の組み合わせをさらに設計へつなぐときは、<a href="/study/game/patterns/component-and-ecs.html">ComponentとECS</a>へ進みます。フレームごとの更新は<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a>で扱います。</p>',19)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
